import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong(), k = (int) nextLong();
        int[] a = new int[n * m];
        for (int i = 0; i < n * m; i++) a[i] = (int) nextLong();
        if (a[0] != 0 || a[n * m - 1] != 0) {
            System.out.println(-1);
            return;
        }
        // BFS where one jump scans up to k cells in a direction, stopping at a wall.
        int[] dist = new int[n * m];
        java.util.Arrays.fill(dist, -1);
        dist[0] = 0;
        int[] queue = new int[n * m];
        int head = 0, tail = 0;
        queue[tail++] = 0;
        int[] di = {1, -1, 0, 0}, dj = {0, 0, 1, -1};
        while (head < tail) {
            int p = queue[head++], i = p / m, j = p % m;
            for (int d = 0; d < 4; d++)
                for (int step = 1; step <= k; step++) {
                    int u = i + di[d] * step, v = j + dj[d] * step;
                    if (u < 0 || u >= n || v < 0 || v >= m) break;
                    int z = u * m + v;
                    if (a[z] != 0) break;
                    if (dist[z] < 0) {
                        dist[z] = dist[p] + 1;
                        queue[tail++] = z;
                    }
                }
        }
        System.out.println(dist[n * m - 1]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m, k := int(nextInt()), int(nextInt()), int(nextInt())
	a := make([]int64, n*m)
	for i := range a {
		a[i] = nextInt()
	}
	if a[0] != 0 || a[n*m-1] != 0 {
		fmt.Println(-1)
		return
	}
	// BFS where one jump scans up to k cells in a direction, stopping at a wall.
	dist := make([]int, n*m)
	for i := range dist {
		dist[i] = -1
	}
	dist[0] = 0
	queue := []int{0}
	di, dj := [4]int{1, -1, 0, 0}, [4]int{0, 0, 1, -1}
	for head := 0; head < len(queue); head++ {
		p := queue[head]
		i, j := p/m, p%m
		for d := 0; d < 4; d++ {
			for step := 1; step <= k; step++ {
				u, v := i+di[d]*step, j+dj[d]*step
				if u < 0 || u >= n || v < 0 || v >= m {
					break
				}
				z := u*m + v
				if a[z] != 0 {
					break
				}
				if dist[z] < 0 {
					dist[z] = dist[p] + 1
					queue = append(queue, z)
				}
			}
		}
	}
	fmt.Println(dist[n*m-1])
}
